// && (VA) va || (YOKI) — ikki sensordan aqlli qaror
const int LDR = A0, PIR = 2;
const int CHIROQ = 9, ZUMMER = 8;

void setup() {
  pinMode(PIR, INPUT);
  pinMode(CHIROQ, OUTPUT); pinMode(ZUMMER, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  bool qorongi = (analogRead(LDR) < 400);
  bool harakat = (digitalRead(PIR) == HIGH);

  // VA: chiroq FAQAT qorong'i BO'LSA VA harakat BO'LSA yonadi
  if (qorongi && harakat) {
    digitalWrite(CHIROQ, HIGH);
    Serial.println("qorong'i VA harakat -> chiroq yondi");
  } else {
    digitalWrite(CHIROQ, LOW);
  }

  // YOKI: signal ikki sababdan bittasi bo'lsa ham chiqadi
  if (harakat || !qorongi) {
    // ... kuzatuv yozuvi
  }

  Serial.print("qorong'i="); Serial.print(qorongi);
  Serial.print("  harakat="); Serial.println(harakat);
  delay(300);
}

// Sensor qiymatini LCD ekranda jonli ko'rsatish
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

const int LDR = A0, TERM = A1;
unsigned long oxirgi = 0;

void setup() {
  lcd.init(); lcd.backlight();
  Serial.begin(9600);
  lcd.setCursor(0, 0); lcd.print("Yorug'lik:");
  lcd.setCursor(0, 1); lcd.print("Harorat:");
}

void loop() {
  // ekranni tez-tez yangilash uni "titratadi" — 300 ms yetarli
  if (millis() - oxirgi < 300) return;
  oxirgi = millis();

  int y = map(analogRead(LDR), 0, 1023, 0, 100);
  int t = map(analogRead(TERM), 0, 1023, 0, 50);

  lcd.setCursor(11, 0);
  lcd.print(y); lcd.print("%  ");      // orqadagi probellar eski raqamni o'chiradi

  lcd.setCursor(11, 1);
  lcd.print(t); lcd.print("C  ");

  Serial.print("yorug'lik="); Serial.print(y);
  Serial.print("  harorat="); Serial.println(t);
}
